def chain_follow(chain):
    chain_dict = {}
    for token in chain:
        if token not in chain_dict:
            chain_dict[token] = []

    current = chain_dict['elk']
    chain_dict['elk'] = []

    while current:
        next_token = current[0]
        chain_dict[next_token].append(current[1])
        current = chain_dict[next_token].pop(0)

    return chain_dict['elk']
